"""CSH-031 behavior through command strings, scripts, and stdin."""
import errno
import os

def add_evaluation_cases(cross, helper):
    def args(name, script, stdout='', status=0, stderr='', **kw):
        if 'files' in kw:
            kw['files'] = {name: {'type': 'file', 'content': value} for name, value in kw['files'].items()}
        cross('evaluation: ' + name, script, stdout=stdout, status=status, stderr=stderr, **kw)
    args('eval joins and shares state', "eval 'a=joined;' 'printf \"%s\\n\" \"$a\"'; printf '%s\\n' \"$a\"\n", 'joined\njoined\n')
    args('eval empty succeeds', 'false; eval; printf "%s\\n" "$?"; eval "" ""\n', '0\n')
    args('eval ordinary failure continues', 'eval false; printf "%s\\n" "$?"\n', '1\n')
    args('eval return leaves function', 'f() { eval "return 7"; echo never; }; f; echo "$?"\n', '7\n')
    args('eval loop transfer', 'for i in a b; do eval break; echo never; done; echo ok\n', 'ok\n')
    args('eval parse failure', "eval 'if'; echo never\n", status=2, stderr='cshell: unterminated command group\n')
    args('eval exit', 'eval "exit 13"; echo never\n', status=13)
    args('dot PATH and parameters', 'set -- original; PATH=.:/bin:/usr/bin; . sourced inner; printf "%s:%s:%s\\n" "$1" "$a" "$?"\n',
         'inner\noriginal:changed:7\n', setup={'sourced': 'echo "$1"\na=changed\nreturn 7\necho never\n'})
    args('dot no args keeps changes to positionals', '. ./sourced; echo "$1:$?"\n', 'new:0\n', setup={'sourced': 'set -- new\n'})
    args('dot last failure continues', '. ./sourced; echo "$?"\n', '1\n', setup={'sourced':'false\n'})
    args('dot empty', 'false; . ./sourced; echo "$?"\n', '0\n', setup={'sourced':''})
    args('dot does not search cwd implicitly', 'PATH=/bin:/usr/bin; . sourced; echo never\n', status=1,
         stderr='cshell: cannot find readable dot file\n', setup={'sourced':'echo never\n'})
    args('dot missing operand', '.\n', status=2, stderr='cshell: dot requires a file\n')
    args('nested dot return', '. ./outer; echo "$?"\n', 'inner:8\n9\n', setup={'outer':'. ./inner\necho "inner:$?"\nreturn 9\n','inner':'return 8\n'})
    args('dot input separate from read', '. ./sourced <data; echo "$v"\n', 'payload\n', setup={'sourced':'read v\n','data':'payload\n'})
    args('dot args restore after nested failure', 'set -- old; command . ./sourced new; echo "$1:$?"\n', 'old:2\n', setup={'sourced':'command return bad\n'}, stderr='cshell: return: numeric status required\n')
    args('alias complete line timing', "alias csh_say='echo hello'\ncsh_say\nunalias csh_say\ncommand -v csh_say; echo \"$?\"\n", 'hello\n1\n')
    args('aliases in eval dot and substitutions', "alias csh_say='echo hello'\neval csh_say\n. ./sourced\necho \"$(csh_say)\"\necho \"`csh_say`\"\n", 'hello\nhello\nhello\nhello\n', setup={'sourced':'csh_say\n'})
    args('alias definition from eval', "eval \"alias csh_say='echo new'\"\ncsh_say\n", 'new\n')
    args('alias function definition timing', "alias csh_say='echo old'\nf() { csh_say; }\nalias csh_say='echo new'\nf\ncsh_say\n", 'old\nnew\n')
    args('alias isolation', "alias csh_say='echo parent'\n( alias csh_say='echo child'; eval csh_say )\ncsh_say\n", 'child\nparent\n')
    args('alias listing', "alias b=two a=one\nalias\nunalias -a\nalias\n", "a='one'\nb='two'\n")
    args('alias operand error', 'alias missing; echo "$?"\n', '1\n', stderr='alias: missing: not found\n')
    args('unalias operand error', 'unalias missing; echo "$?"\n', '1\n', stderr='unalias: missing: not found\n')
    args('command bypass function', 'echo() { printf "function\\n"; }; echo; command echo external\n', 'function\nexternal\n')
    args('command suppresses special assignment', 'a=old; a=new command eval ":"; echo "$a"\na=persist eval ":"; echo "$a"\n', 'old\npersist\n')
    args('command special error continues', 'command shift 99; echo "$?"\n', '1\n', stderr='cshell: shift: count exceeds positional parameters\n')
    args('command declaration context', 'v="two words"; command -p export name=$v; printf "<%s>\\n" "$name"\n', '<two words>\n')
    args('command default PATH preserves environment', 'PATH=/missing command -p sh -c \'printf "%s\\n" "$PATH"\'\n', '/missing\n')
    args('command intrinsic without PATH', 'PATH=/missing; command -v read; command -v cd; command -v eval\n', 'read\ncd\neval\n')
    args('lookup alias function reserved', "alias hello='echo hi'\nf() { :; }\ncommand -v hello f if; command -V read; type f\n", "alias hello='echo hi'\nf\nif\nread is a shell builtin\nf is a function\n")
    args('lookup missing', 'command -v no-such-cshell-command; echo "$?"\n', '1\n')
    args('lookup options', 'command -z; echo "$?"\n', '2\n', stderr='cshell: command: invalid option\n')
    args('exec replacement PID and exports', f'a=value exec {helper} args "$a"\necho never\n', '[]\n')
    args('exec inherits prefix environment', "a=value exec /bin/sh -c 'echo \"$a\"'\n", 'value\n')
    args('exec same PID', "exec /bin/sh -c '[ \"$$\" = \"$1\" ]' sh \"$$\"\n")
    args('exec missing command', 'exec no-such-cshell-command\necho never\n', status=127, stderr='cshell: no-such-cshell-command: command not found\n')
    args('exec no command persistent fd', 'exec 3>out; echo first >&3; command exec 4>&3; echo second >&4; exec 3>&- 4>&-; cat out\n', 'first\nsecond\n', files={'out':'first\nsecond\n'})
    args('exec standard output persists', 'exec >out; echo one; echo two\n', files={'out':'one\ntwo\n'})
    args('exec redirects in eval unwind outer only', 'eval "exec >inner; echo inner" >outer; echo after\n', 'after\n', files={'inner':'inner\n','outer':''})
    args('hash remember reset and builtin exclusion', 'PATH=/bin:/usr/bin; hash echo read; hash; hash -r; hash\n', '/bin/echo\n')
    args('hash PATH invalidates', 'PATH=/bin:/usr/bin; hash echo; PATH=/usr/bin:/bin; hash\n')
    args('hash missing', 'hash no-such-cshell-command; echo "$?"\n', '1\n', stderr='cshell: no-such-cshell-command: command not found\n')
    args('hash invalid option', 'hash -z; echo "$?"\n', '2\n', stderr='cshell: hash: invalid option\n')
    args('read fields remainder', 'read a b <data; printf "<%s><%s>:%s\\n" "$a" "$b" "$?"\n', '<one><two   three>:0\n', setup={'data':'  one  two   three  \n'})
    args('read nonwhite IFS', "IFS=: read a b c <data; printf '<%s><%s><%s>\\n' \"$a\" \"$b\" \"$c\"\n", '<><one><two:three:>\n', setup={'data':':one:two:three:\n'})
    args('read escape protects delimiter', 'read a b <data; printf "<%s><%s>\\n" "$a" "$b"\n', '<one two><three>\n', setup={'data':'one\\ two three\n'})
    args('read continuation', 'read a <data; echo "$a:$?"\n', 'onetwo:0\n', setup={'data':'one\\\ntwo\n'})
    args('read raw', 'read -r a <data; printf "%s\\n" "$a"\n', 'one\\ two\n', setup={'data':'one\\ two\n'})
    args('read delimiter and next read', 'exec 3<data; read -d : a <&3; read b <&3; echo "$a/$b"\n', 'one/two\n', setup={'data':'one:two\n'})
    args('read EOF partial', 'read a b <data; echo "$a/$b:$?"\n', 'one/two:1\n', setup={'data':'one two'})
    args('read empty EOF clears names', 'a=old; read a <data; echo "$a:$?"\n', ':1\n', setup={'data':''})
    args('read empty IFS', 'IFS= read a <data; printf "<%s>\\n" "$a"\n', '<  spaced  >\n', setup={'data':'  spaced  \n'})
    args('read invalid name', 'read 1bad <data; echo "$?"\n', '2\n', stderr='cshell: read: invalid variable name\n', setup={'data':'one\n'})
    args('read readonly', 'readonly a; read a <data; echo "$?"\n', '2\n', stderr='cshell: read: readonly variable\n', setup={'data':'one\n'})
    args('read option error', 'read -z a; echo "$?"\n', '2\n', stderr='cshell: read: invalid option\n')
    args('read missing operand', 'read; echo "$?"\n', '2\n', stderr='cshell: read: variable required\n')
    args('getopts grouped and required argument', 'set -- -abvalue -- tail; while getopts ab: opt; do echo "$opt:${OPTARG-unset}:$OPTIND"; done; echo "$opt:$OPTIND:$?"\n', 'a:unset:1\nb:value:2\n?:3:0\n')
    args('getopts explicit reset', 'getopts ab opt -ab; echo "$opt:$OPTIND"; OPTIND=1; getopts ab opt -ab; echo "$opt:$OPTIND"; getopts ab opt -ab; echo "$opt:$OPTIND"\n', 'a:1\na:1\nb:2\n')
    args('getopts silent errors', 'getopts :ab: opt -x; echo "$opt:$OPTARG:$?"; OPTIND=1; getopts :b: opt -b; echo "$opt:$OPTARG:$?"\n', '?:x:0\n::b:0\n')
    args('getopts diagnostic errors', 'getopts a opt -x; echo "$opt:${OPTARG-unset}:$?"; OPTIND=1; getopts b: opt -b; echo "$opt:${OPTARG-unset}:$?"\n', '?:unset:0\n?:unset:0\n', stderr='cshell: getopts: illegal option -- x\ncshell: getopts: option requires an argument -- b\n')
    args('getopts end', 'getopts a opt operand; echo "$opt:$OPTIND:$?"\n', '?:1:1\n')
    args('getopts missing operands', 'getopts; echo "$?"\n', '2\n', stderr='cshell: getopts: optstring and variable required\n')
    args('getopts invalid state', 'OPTIND=bad; getopts a opt -a; echo "$?"\n', '2\n', stderr='cshell: getopts: invalid OPTIND\n')
    args('umask numeric symbolic isolation', 'umask 027; umask; umask -S; (umask 077); umask; umask u=rwx,g=rx,o=; umask\n', '0027\nu=rwx,g=rx,o=\n0027\n0027\n')
    args('umask symbolic copying', 'umask 077; umask g=u,o=g; umask; umask a-w; umask\n', '0000\n0222\n')
    args('umask error preserves state', 'umask 027; umask 999; echo "$?"; umask\n', '2\n0027\n', stderr='cshell: umask: invalid mask\n')
    args('ulimit child mutation', '(ulimit -S -f 1024; ulimit -S -f); echo "$?"\n', '1024\n0\n')
    args('ulimit invalid option', 'ulimit -z; echo "$?"\n', '2\n', stderr='cshell: ulimit: invalid option\n')
    args('ulimit invalid value', 'ulimit -f bad; echo "$?"\n', '2\n', stderr='cshell: ulimit: invalid limit\n')
    args('times format', 'times >record; { read a b; read c d; } <record; case "$a/$b/$c/$d" in *m*s/*m*s/*m*s/*m*s) echo ok;; *) echo bad;; esac\n', 'ok\n')
    args('times operand error suppressed', 'command times bad; echo "$?"\n', '2\n', stderr='cshell: times: unexpected operand\n')
    args('host utility inventory', 'command -p true; command -p false; echo "$?"; command -p test a = a; command -p [ a = a ]; command -p printf "%s\\n" ok; command -p echo done\n', '1\nok\ndone\n')

    args('private source descriptors survive exec', '. ./sourced; echo after\n', 'inside\nafter\n', setup={'sourced':'exec 10>/dev/null 11>/dev/null 12>/dev/null\necho inside\n'})
    args('eval private descriptor isolation', "eval 'exec 10>/dev/null'; echo after\n", 'after\n')
    args('empty lookup and exec end options', 'command; command --; exec --; echo ok\n', 'ok\n')
    args('pwd follows PATH', 'PATH=/missing; command -v pwd; command -p echo "$?"\n', '1\n')
    args('exec pipeline isolation', 'exec echo child | cat; echo parent\n', 'child\nparent\n')
    args('alias quoted name not substituted', "alias echo='printf alias'\ncommand echo literal\n", 'literal\n')
    args('getopts separate argument', 'getopts a: opt -a value; echo "$opt:$OPTARG:$OPTIND"\n', 'a:value:3\n')
    args('getopts subshell cursor isolated', 'getopts abc opt -abc; (getopts abc opt -abc); getopts abc opt -abc; echo "$opt"\n', 'b\n')
    args('read empty delimiter', "read -d '' a <data; echo \"$a:$?\"\n", 'one:0\n', setup={'data':'one\0two'})
    args('read missing delimiter operand', 'read -d; echo "$?"\n', '2\n', stderr='cshell: read: -d requires a delimiter\n')
    args('read input error', 'read a <&-; echo "$?"\n', '2\n', stderr='cshell: read: cannot read input\n')
    args('type missing', 'type no-such-cshell-command; echo "$?"\n', '1\n', stderr='cshell: no-such-cshell-command: not found\n')
    args('umask operand count', 'umask 0 1; echo "$?"\n', '2\n', stderr='cshell: umask: too many operands\n')
    args('ulimit option inventory', 'ulimit -a >limits; while read option value; do printf "%s\\n" "$option"; done <limits\n', '-c\n-d\n-f\n-n\n-s\n-v\n-t\n')
    args('ulimit all rejects mutation', 'ulimit -a 1; echo "$?"\n', '2\n', stderr='cshell: ulimit: invalid operands\n')

    args('command dot suppresses own error', 'command . ./missing; echo "$?"\n', '1\n', stderr='cshell: cannot find readable dot file\n')
    args('command eval suppresses nested special property only', "command eval 'false'; echo \"$?\"\n", '1\n')

    args('umask affects creation', f'umask 027; : >created; {helper} mode created\n', '640\n')
    args('exec permission failure', 'exec ./denied\necho never\n', status=126, setup={'denied':'echo never\n'}, stderr=f'cshell: ./denied: cannot execute: {os.strerror(errno.EACCES)}\n')
    args('command redirection error continues input', 'command exec >missing/path\necho after\n', 'after\n', stderr=f'cshell: cannot apply redirection: {os.strerror(errno.ENOENT)}\n')
    args('hash dotted utility and stale retry', 'chmod +x first/utility.tool second/utility.tool; PATH=first:second:/bin:/usr/bin; hash utility.tool; utility.tool; rm first/utility.tool; utility.tool\n', 'first\nsecond\n', setup={'first/utility.tool':'echo first\n','second/utility.tool':'echo second\n'})
    args('lookup absolute output for relative PATH', 'chmod +x local/tool; PATH=local:/bin:/usr/bin; p=$(command -v tool); case "$p" in /*/local/tool) echo absolute;; esac\n', 'absolute\n', setup={'local/tool':'echo tool\n'})

    args('source return inherited by subshell', '. ./sourced; echo after\n', '7\nafter\n', setup={'sourced':'(return 7)\necho "$?"\n'})

    args('hash end of options listing', 'PATH=/bin:/usr/bin; hash echo; hash --\n', '/bin/echo\n')
    args('exec end options permits dash name', "chmod +x ./-utility; PATH=.:/bin:/usr/bin; exec -- -utility\n", 'dash\n', setup={'-utility':'echo dash\n'})

    args('command forwards existing monitor options', 'command set -m; echo "$?"; command set +m; command set -- word; echo "$1"\n', '1\nword\n', stderr='cshell: set: job control unavailable\n')

    args('dot supports readable device input', '. /dev/null; echo "$?"\n', '0\n')
